fn diff_color(source: &str, target: &str) -> Vec<(String, bool)> {
    let s1: Vec<char> = source.chars().collect();
    let s2: Vec<char> = target.chars().collect();
    let n = s1.len();
    let m = s2.len();
    let mut dp = vec![vec![0; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if s1[i - 1] == s2[j - 1] { dp[i][j] = dp[i - 1][j - 1] + 1; }
            else { dp[i][j] = std::cmp::max(dp[i - 1][j], dp[i][j - 1]); }
        }
    }
    let mut result = Vec::new();
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
        if s1[i - 1] == s2[j - 1] {
            result.push((s1[i - 1].to_string(), false));
            i -= 1; j -= 1;
        } else if dp[i - 1][j] >= dp[i][j - 1] { i -= 1; }
        else {
            result.push((s2[j - 1].to_string(), true));
            j -= 1;
        }
    }
    while j > 0 {
        result.push((s2[j - 1].to_string(), true));
        j -= 1;
    }
    result.reverse();
    if result.is_empty() { return vec![]; }
    let mut merged = Vec::new();
    let (mut curr_s, mut curr_b) = result[0].clone();
    for idx in 1..result.len() {
        if result[idx].1 == curr_b { curr_s.push_str(&result[idx].0); }
        else {
            merged.push((curr_s, curr_b));
            curr_s = result[idx].0.clone();
            curr_b = result[idx].1;
        }
    }
    merged.push((curr_s, curr_b));
    merged
}

fn main() {
    let cli = Cli::parse();
    match cli.command {
        Commands::Regex { expression, replacement, paths, dry_run, force, backup, silent, color, dump, dump_prefix, no_dump, replace_limit, replace_transform, include_dirs, recursive, max_depth, hidden } => {
            let is_dry_run = !force || dry_run;
            setup_color(color);
            let re = Regex::new(&expression).expect("Invalid regex");
            let mut ops = Vec::new();
            let mut visited = HashSet::new();
            for p in paths {
                let path = PathBuf::from(p);
                if !path.exists() { continue; }
                if path.is_dir() {
                    let mut walker = WalkDir::new(&path).contents_first(true);
                    if let Some(d) = max_depth { walker = walker.max_depth(d); }
                    if !recursive { walker = walker.max_depth(0); }
                    for entry in walker {
                        let entry = entry.unwrap();
                        if !hidden && is_hidden(entry.path(), &path) { continue; }
                        if entry.path().is_dir() && !include_dirs { continue; }
                        if entry.path() == path && !include_dirs && entry.path().is_dir() { continue; }
                        process_path(entry.path(), &re, &replacement, replace_limit, replace_transform, &mut ops, &mut visited);
                    }
                } else {
                    process_path(&path, &re, &replacement, replace_limit, replace_transform, &mut ops, &mut visited);
                }
            }
            execute_ops(ops, is_dry_run, backup, silent, dump || (force && !no_dump), dump_prefix);
        }
        Commands::ToAscii { paths, dry_run, force, backup, silent, color, dump, dump_prefix, no_dump, include_dirs, recursive, max_depth, hidden } => {
            let is_dry_run = !force || dry_run;
            setup_color(color);
            let mut ops = Vec::new();
            let mut visited = HashSet::new();
            for p in paths {
                let path = PathBuf::from(p);
                if !path.exists() { continue; }
                if path.is_dir() {
                    let mut walker = WalkDir::new(&path).contents_first(true);
                    if let Some(d) = max_depth { walker = walker.max_depth(d); }
                    if !recursive { walker = walker.max_depth(0); }
                    for entry in walker {
                        let entry = entry.unwrap();
                        if !hidden && is_hidden(entry.path(), &path) { continue; }
                        if entry.path().is_dir() && !include_dirs { continue; }
                        process_to_ascii(entry.path(), &mut ops, &mut visited);
                    }
                } else {
                    process_to_ascii(&path, &mut ops, &mut visited);
                }
            }
            execute_ops(ops, is_dry_run, backup, silent, dump || (force && !no_dump), dump_prefix);
        }
        Commands::FromFile { dumpfile, dry_run, force, backup, silent, color, dump, dump_prefix, no_dump, undo } => {
            let is_dry_run = !force || dry_run;
            setup_color(color);
            let content = fs::read_to_string(dumpfile).expect("Failed to read dump file");
            let dump_data: Dump = serde_json::from_str(&content).expect("Failed to parse dump file");
            let mut ops = Vec::new();
            for op in dump_data.operations {
                let (src, tgt) = if undo { (op.target, op.source) } else { (op.source, op.target) };
                let src_path = PathBuf::from(src);
                let tgt_path = PathBuf::from(tgt);
                let basename = src_path.file_name().unwrap().to_str().unwrap().to_string();
                let tgt_basename = tgt_path.file_name().unwrap().to_str().unwrap().to_string();
                ops.push(RenameOp {
                    source: src_path,
                    target: tgt_path,
                    basename_parts: vec![BasenamePart::Match {
                        original: basename.clone(),
                        replacement: tgt_basename.clone(),
                        diff: diff_color(&basename, &tgt_basename),
                    }],
                });
            }
            execute_ops(ops, is_dry_run, backup, silent, dump || (force && !no_dump), dump_prefix);
        }
    }
}

fn setup_color(mode: ColorMode) {
    match mode {
        ColorMode::Always => colored::control::set_override(true),
        ColorMode::Never => colored::control::set_override(false),
        ColorMode::Auto => {},
    }
}

fn is_hidden(path: &Path, base: &Path) -> bool {
    let rel = path.strip_prefix(base.parent().unwrap_or(base)).unwrap_or(path);
    for component in rel.components() {
        if let Some(s) = component.as_os_str().to_str() {
            if s.starts_with('.') && s != "." && s != ".." { return true; }
        }
    }
    false
}

fn process_path(path: &Path, re: &Regex, replacement: &str, limit: usize, transform: Option<Transform>, ops: &mut Vec<RenameOp>, visited: &mut HashSet<PathBuf>) {
    if !visited.insert(path.to_path_buf()) { return; }
    let basename = if let Some(n) = path.file_name() { n.to_str().unwrap().to_string() } else { return; };
    let mut parts = Vec::new();
    let mut last_end = 0;
    let mut count = 0;
    for cap in re.captures_iter(&basename) {
        if limit > 0 && count >= limit { break; }
        let m = cap.get(0).unwrap();
        if m.start() > last_end { parts.push(BasenamePart::Unchanged(basename[last_end..m.start()].to_string())); }
        let original = m.as_str().to_string();
        let mut replaced = String::new();
        cap.expand(replacement, &mut replaced);
        if let Some(t) = transform {
            replaced = match t {
                Transform::Upper => replaced.to_uppercase(),
                Transform::Lower => replaced.to_lowercase(),
                Transform::Ascii => any_ascii(&replaced),
            };
        }
        parts.push(BasenamePart::Match {
            original: original.clone(),
            replacement: replaced.clone(),
            diff: diff_color(&original, &replaced),
        });
        last_end = m.end();
        count += 1;
    }
    if last_end < basename.len() { parts.push(BasenamePart::Unchanged(basename[last_end..].to_string())); }
    let new_basename: String = parts.iter().map(|p| match p { BasenamePart::Unchanged(s) => s.clone(), BasenamePart::Match { replacement, .. } => replacement.clone() }).collect();
    if new_basename != basename {
        ops.push(RenameOp { source: path.to_path_buf(), target: path.with_file_name(new_basename), basename_parts: parts });
    }
}

fn process_to_ascii(path: &Path, ops: &mut Vec<RenameOp>, visited: &mut HashSet<PathBuf>) {
    if !visited.insert(path.to_path_buf()) { return; }
    let basename = if let Some(n) = path.file_name() { n.to_str().unwrap().to_string() } else { return; };
    let new_basename = any_ascii(&basename);
    if new_basename != basename {
        ops.push(RenameOp {
            source: path.to_path_buf(),
            target: path.with_file_name(&new_basename),
            basename_parts: vec![BasenamePart::Match {
                original: basename.clone(),
                replacement: new_basename.clone(),
                diff: diff_color(&basename, &new_basename),
            }],
        });
    }
}

fn execute_ops(ops: Vec<RenameOp>, dry_run: bool, backup: bool, silent: bool, dump: bool, dump_prefix: String) {
    if ops.is_empty() {
        if !silent { if dry_run { println!("{}", "This is a DRY-RUN".bold()); } }
        if dump { write_dump(Vec::new(), dump_prefix); }
        return;
    }
    // Conflict detection
    let mut targets = HashMap::new();
    for op in &ops { targets.entry(op.target.clone()).or_insert(Vec::new()).push(op.source.clone()); }
    let mut same_name_errors = Vec::new();
    for (tgt, srcs) in &targets { if srcs.len() > 1 { for src in srcs { same_name_errors.push((src.clone(), tgt.clone())); } } }
    if !same_name_errors.is_empty() {
        if !silent {
            if dry_run { println!("{}", "This is a DRY-RUN".bold()); }
            eprintln!("{}{}Files will have the same name\n", "Error: ".red(), "");
            eprint!("{}", "\x1b[31m\x1b[31m".red());
            for (src, tgt) in same_name_errors { eprintln!("{}->{}", src.display(), tgt.display()); }
            eprintln!("{}", "\x1b[0m\x1b[0m".red());
        }
        std::process::exit(1);
    }
    for op in &ops {
        if op.target.exists() && op.source != op.target {
            if !silent {
                if dry_run { println!("{}", "This is a DRY-RUN".bold()); }
                eprintln!("{}Conflict with existing path {} -> {}", "Error: ".red(), op.source.display(), op.target.display());
            }
            std::process::exit(1);
        }
    }

    if !silent && dry_run { println!("{}", "This is a DRY-RUN".bold()); }

    let mut final_ops = Vec::new();
    for op in ops {
        if !silent {
            let src_dir = op.source.parent().unwrap_or(Path::new(""));
            let tgt_dir = op.target.parent().unwrap_or(Path::new(""));
            let mut src_str = format!("{}", src_dir.display());
            if !src_str.is_empty() { src_str.push('/'); }
            let mut tgt_str = format!("{}", tgt_dir.display());
            if !tgt_str.is_empty() { tgt_str.push('/'); }

            print!("{}", src_str.color(Fixed(8)));
            print!("{}", op.source.file_name().unwrap().to_str().unwrap().color(Fixed(8)));
            print!(" -> ");
            print!("{}", tgt_str.green());
            for part in op.basename_parts {
                match part {
                    BasenamePart::Unchanged(s) => print!("{}", s.green()),
                    BasenamePart::Match { diff, .. } => {
                        for (s, added) in diff { if added { print!("{}", s.bold().red()); } else { print!("{}", s.green()); } }
                    }
                }
            }
            println!();
        }
        if !dry_run {
            if backup {
                let mut bkp = op.source.clone();
                let mut bkp_str = bkp.to_str().unwrap().to_string();
                bkp_str.push_str(".bk");
                let mut bkp_path = PathBuf::from(&bkp_str);
                let mut count = 1;
                while bkp_path.exists() {
                    bkp_path = PathBuf::from(format!("{}.{}", bkp_str, count));
                    count += 1;
                }
                if !silent { println!("Info:  Backup created - {} -> {}", op.source.display(), bkp_path.display()); }
                fs::copy(&op.source, bkp_path).unwrap();
            }
            fs::rename(&op.source, &op.target).unwrap();
        }
        final_ops.push(Operation { source: op.source.to_str().unwrap().to_string(), target: op.target.to_str().unwrap().to_string() });
    }
    if dump { write_dump(final_ops, dump_prefix); }
}

fn write_dump(ops: Vec<Operation>, prefix: String) {
    let now = Local::now();
    let filename = format!("{}{}.json", prefix, now.format("%Y-%m-%d_%H%M%S"));
    let dump = Dump { date: now.format("%Y-%m-%d %H:%M:%S").to_string(), operations: ops };
    let content = serde_json::to_string_pretty(&dump).unwrap();
    fs::write(filename, content).unwrap();
}

use std::collections::HashMap as Map;
EOF
