fn process_path(path: &Path, re: &Regex, replacement: &str, limit: usize, transform: Option<Transform>, ops: &mut Vec<RenameOp>, visited: &mut HashSet<PathBuf>) {
    if !visited.insert(path.to_path_buf()) { return; }
    let basename = if let Some(n) = path.file_name() { n.to_str().unwrap().to_string() } else { return; };
    let mut parts = Vec::new();
    let mut last_end = 0;
    let mut count = 0;
    for cap in re.captures_iter(&basename) {
        if limit > 0 && count >= limit { break; }
        let m = cap.get(0).unwrap();
        if m.start() > last_end { parts.push(BasenamePart::Unchanged(basename[last_end..m.start()].to_string())); }
        let original = m.as_str().to_string();
        let mut replaced = String::new();
        cap.expand(replacement, &mut replaced);
        if let Some(t) = transform {
            replaced = match t {
                Transform::Upper => replaced.to_uppercase(),
                Transform::Lower => replaced.to_lowercase(),
                Transform::Ascii => any_ascii(&replaced),
            };
        }
        parts.push(BasenamePart::Match {
            original: original.clone(),
            replacement: replaced.clone(),
            diff: diff_color(&original, &replaced),
        });
        last_end = m.end();
        count += 1;
    }
    if last_end < basename.len() { parts.push(BasenamePart::Unchanged(basename[last_end..].to_string())); }
    let new_basename: String = parts.iter().map(|p| match p { BasenamePart::Unchanged(s) => s.clone(), BasenamePart::Match { replacement, .. } => replacement.clone() }).collect();
    if new_basename != basename {
        ops.push(RenameOp { source: path.to_path_buf(), target: path.with_file_name(new_basename), basename_parts: parts });
    }
}

fn process_to_ascii(path: &Path, ops: &mut Vec<RenameOp>, visited: &mut HashSet<PathBuf>) {
