    let basename = if let Some(n) = path.file_name() { n.to_str().unwrap().to_string() } else { return; };
    let new_basename = any_ascii(&basename);
    if new_basename != basename {
        ops.push(RenameOp {
            source: path.to_path_buf(),
            target: path.with_file_name(&new_basename),
