            if s1[i - 1] == s2[j - 1] { dp[i][j] = dp[i - 1][j - 1] + 1; }
            else { dp[i][j] = std::cmp::max(dp[i - 1][j], dp[i][j - 1]); }
        }
    }
    let mut result = Vec::new();
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
