def process_path(path, regex, args, ops, visited):
    if str(path) in visited: return
    visited.add(str(path))
    basename = path.name
    parts = []
    last_end = 0
    count = 0
    for match in regex.finditer(basename):
        if args.replace_limit > 0 and count >= args.replace_limit: break
        if match.start() > last_end:
            parts.append((basename[last_end:match.start()], False))

        orig = match.group(0)
        repl = args.replacement
        repl_py = re.sub(r'\$(\d+)', r'\\\1', repl)
        repl_py = re.sub(r'\$\{(\d+)\}', r'\\\1', repl_py)
        try:
            replaced = match.expand(repl_py)
        except re.error:
            replaced = repl # Fallback if expansion fails

        if args.replace_transform == "upper": replaced = replaced.upper()
        elif args.replace_transform == "lower": replaced = replaced.lower()
        elif args.replace_transform == "ascii": replaced = to_ascii_func(replaced)

        parts.append((lcs_diff(orig, replaced), True))
        last_end = match.end()
        count += 1
    if last_end < len(basename):
        parts.append((basename[last_end:], False))

    new_name = "".join([p[0] if not p[1] else "".join([d[0] for d in p[0]]) for p in parts])
    if new_name != basename:
        ops.append(RenameOp(path, path.with_name(new_name), parts))

def walk_ascii(base_path, args, ops, visited):
