        elif args.replace_transform == "ascii": replaced = to_ascii_func(replaced)

        parts.append((lcs_diff(orig, replaced), True))
        last_end = match.end()
        count += 1
    if last_end < len(basename):
        parts.append((basename[last_end:], False))

    new_name = "".join([p[0] if not p[1] else "".join([d[0] for d in p[0]]) for p in parts])
    if new_name != basename:
        ops.append(RenameOp(path, path.with_name(new_name), parts))

def walk_ascii(base_path, args, ops, visited):
    for root, dirs, files in os.walk(base_path, topdown=False):
        root_path = Path(root)
        try:
            rel = root_path.relative_to(base_path)
            depth = len(rel.parts)
        except ValueError:
            depth = 0
        if args.max_depth is not None and depth > args.max_depth: continue
        if not args.recursive and depth > 0: continue

        to_process = []
        if args.include_dirs: to_process.extend(sorted(dirs))
        to_process.extend(sorted(files))

        for name in to_process:
            path = root_path / name
            if not args.hidden and is_hidden(path, base_path): continue
            process_ascii(path, args, ops, visited)
    if args.include_dirs:
        process_ascii(base_path, args, ops, visited)

def process_ascii(path, args, ops, visited):
    if str(path) in visited: return
    visited.add(str(path))
    basename = path.name
    new_name = to_ascii_func(basename)
    if new_name != basename:
        ops.append(RenameOp(path, path.with_name(new_name), [(lcs_diff(basename, new_name), True)]))

def execute_ops(ops, dry_run, args):
    if not ops:
        if not args.silent:
            if dry_run: print(f"{BOLD}This is a DRY-RUN{RESET}")
        if (not dry_run or args.dump) and not args.no_dump: write_dump([], args.dump_prefix)
        return

    targets = {}
    for op in ops:
        targets.setdefault(str(op.target), []).append(op.source)

    same_name = []
    for tgt, srcs in targets.items():
        if len(srcs) > 1:
            for src in srcs: same_name.append((src, tgt))

    if same_name:
        if not args.silent:
            if dry_run: print(f"{BOLD}This is a DRY-RUN{RESET}")
            sys.stderr.write(f"{RED}Error: {RESET}Files will have the same name\n\n")
            sys.stderr.write(f"{RED}{RED}")
            for src, tgt in same_name:
                sys.stderr.write(f"{src}->{tgt}\n")
            sys.stderr.write(f"{RESET}{RESET}")
        sys.exit(1)

    for op in ops:
        if op.target.exists() and op.source != op.target:
            if not args.silent:
                if dry_run: print(f"{BOLD}This is a DRY-RUN{RESET}")
                sys.stderr.write(f"{RED}Error: {RESET}Conflict with existing path {op.source} -> {op.target}\n")
            sys.exit(1)

    if not args.silent and dry_run: print(f"{BOLD}This is a DRY-RUN{RESET}")

    final_ops = []
    for op in ops:
        print_op(op, dry_run, args.silent)
        if not dry_run:
            if args.backup:
                bkp = str(op.source) + ".bk"
                count = 1
                while os.path.exists(bkp):
                    bkp = f"{op.source}.bk.{count}"
                    count += 1
                if not args.silent: print(f"Info:  Backup created - {op.source} -> {bkp}")
                import shutil
                shutil.copy2(op.source, bkp)
            os.rename(op.source, op.target)
        final_ops.append({"source": str(op.source), "target": str(op.target)})

    if (not dry_run or args.dump) and not args.no_dump:
        write_dump(final_ops, args.dump_prefix)

def write_dump(ops, prefix):
    now = datetime.now()
    filename = f"{prefix}{now.strftime('%Y-%m-%d_%H%M%S')}.json"
    data = {
        "date": now.strftime("%Y-%m-%d %H:%M:%S"),
        "operations": ops
    }
    with open(filename, "w") as f:
        json.dump(data, f, indent=2)

if __name__ == "__main__":
    main()
